def scr(n, shot, col, row, marks=(), cap=""): return dict(n=n, kind="screen", shot=shot, col=col, row=row, marks=list(marks), cap=cap)
def box(n, kind, col, row, title, text=""): return dict(n=n, kind=kind, col=col, row=row, title=title, text=text)

