used = sorted({n['shot'] for p in PROCS for n in p['nodes'] if n['kind'] == 'screen'})
shots = []
for sid in used:
    setup, full, post = SHOTS[sid]
    sels = []
    for p in PROCS:
        for n in p['nodes']:
            if n['kind'] == 'screen' and n['shot'] == sid:
                for sel, _ in n['marks']:
                    if sel not in sels: sels.append(sel)
    typ = None
    if post.startswith('TYPE:'):
        _, sel, val = post.split(':', 2); typ = [sel, val]; post = ''
    shots.append(dict(id=sid, setup=setup, full=full, post=post, type=typ, sels=sels, wait=2200 if 'kaart' in sid else 700))
json.dump({"procs": PROCS, "shots": shots}, open(os.path.join(D, 'procs.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(len(PROCS), "processes;", len(shots), "screens")
